targets.rawSql:
SELECT set_config('plux.organization_id', ${organization:sqlstring}, false);
SELECT GREATEST(0, 1 - COALESCE(SUM(r.events) FILTER (WHERE r.event_name = 'fatal_error'), 0)::float8
  / NULLIF(SUM(r.events) FILTER (WHERE r.event_name = 'session_start'), 0)) AS "Crash-free sessions"
FROM analytics_rollups r
WHERE r.organization_id = NULLIF(${organization:sqlstring}, '')::uuid
  AND r.granularity = ${granularity:sqlstring}
  AND $__timeFilter(r.bucket)
  AND r.app_id::text IN ($app)
  AND r.release_sequence::text IN ($release);

SELECT set_config('plux.organization_id', ${organization:sqlstring}, false);
SELECT 1000.0 * SUM(r.events) FILTER (WHERE r.event_name = 'error') / NULLIF(SUM(r.events) FILTER (WHERE r.event_name = 'session_start'), 0) AS "Errors per 1000 sessions"
FROM analytics_rollups r
WHERE r.organization_id = NULLIF(${organization:sqlstring}, '')::uuid
  AND r.granularity = ${granularity:sqlstring}
  AND $__timeFilter(r.bucket)
  AND r.app_id::text IN ($app)
  AND r.release_sequence::text IN ($release);
